head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > createSubmission]<br/>Submission 을 동적으로 생성합니다. 동일 ID 의 Submission 이 이미 존재하는 경우 기존 Submission 을 삭제 후 재생성합니다.",
    "validation" : [
        "submissionInfo.requestHeader(선택) 로 HTTP Request Header 에 키-값 쌍을 추가할 수 있어야 합니다.",
        "submissionInfo.preSubmitFunc(선택) 로 Submission 실행 전 호출할 전처리 함수를 함수명 문자열 또는 함수 참조로 지정할 수 있어야 합니다.",
        "submissionInfo.submitHandler(선택) 가 false 를 반환하면 Submission 요청이 취소되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 시나리오 2 : preSubmitFunc 로 지정할 전처리 함수 (함수명 문자열로 지정)
scwin.myPreSubmit = function (e) {
    scwin.preSubmitCalled = true;
    console.log("preSubmitFunc 호출됨");
};

// preSubmitFunc 호출 여부 플래그
scwin.preSubmitCalled = false;



scwin.btn_createSubmission_onclick = function () {
    var scenario = par_scenario.getValue();

    // 이전 시나리오에서 남아있을 수 있는 Process Message 정리
    $p.hideProcessMessage();

    // 매 시나리오 실행 시 이전 데이터 제거
    dlt_userList.removeAll();

    if (scenario === "1") {
        // 시나리오 1 : requestHeader 추가
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : requestHeader 추가 ──");

        // XMLHttpRequest.setRequestHeader 패치로 실제 설정된 헤더 수집
        var collected = [];
        var origSetRequestHeader = XMLHttpRequest.prototype.setRequestHeader;
        XMLHttpRequest.prototype.setRequestHeader = function (key, value) {
            collected.push(key + "=" + value);
            return origSetRequestHeader.apply(this, arguments);
        };

        var submissionInfo = {
            "id" : "sbm_header",
            "action" : "/data/$p_createSubmission_userList.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "requestHeader" : {
                "X-Custom-Token" : "test_token_123",
                "X-Client-Ver" : "5.0"
            },
            "submitDoneHandler" : function (e) {
                // 원본 setRequestHeader 복구
                XMLHttpRequest.prototype.setRequestHeader = origSetRequestHeader;

                // 설정된 requestHeader 필터링 (커스텀 헤더만)
                var filtered = collected.filter(function (h) {
                    return h.indexOf("X-Custom-Token") === 0 || h.indexOf("X-Client-Ver") === 0;
                });
                wf_body_bottom.getObj("scwin").setReturnValue("설정된 requestHeader: " + filtered.join(", "));
                wf_body_bottom.getObj("scwin").setReturnValue("응답 OK (responseStatusCode=" + e.responseStatusCode + ")");
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                XMLHttpRequest.prototype.setRequestHeader = origSetRequestHeader;
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler: errorType=" + e.errorType);
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_header");
    } else if (scenario === "2") {
        // 시나리오 2 : preSubmitFunc 호출 확인 (함수명 문자열로 지정)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : preSubmitFunc 호출 확인 ──");

        scwin.preSubmitCalled = false;

        var submissionInfo = {
            "id" : "sbm_preSubmit",
            "action" : "/data/$p_createSubmission_userList.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "preSubmitFunc" : "scwin.myPreSubmit",
            "submitDoneHandler" : function (e) {
                if (scwin.preSubmitCalled === true) {
                    wf_body_bottom.getObj("scwin").setReturnValue("preSubmitFunc 호출됨 + 응답 OK (행 수=" + dlt_userList.getRowCount() + ")");
                } else {
                    wf_body_bottom.getObj("scwin").setReturnValue("preSubmitFunc 미호출 + 응답 OK");
                }
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler: errorType=" + e.errorType);
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_preSubmit");
    } else if (scenario === "3") {
        // 시나리오 3 : submitHandler true/false 분기
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : submitHandler 반환값 분기 ──");

        var returnValue = par_submitReturn.getValue();
        var isReturnTrue = (returnValue === "true");

        var submissionInfo = {
            "id" : "sbm_handler",
            "action" : "/data/$p_createSubmission_userList.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "submitHandler" : function (e) {
                return isReturnTrue;
            },
            "submitDoneHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitHandler 반환값=" + returnValue + " / 데이터 로드 여부=true (행 수=" + dlt_userList.getRowCount() + ")");
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler: errorType=" + e.errorType);
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_handler");

        // submitHandler 가 false 를 반환한 경우 done/error 어느쪽도 호출되지 않으므로 setTimeout 으로 확인
        $p.setTimeout(function () {
            if (isReturnTrue === false) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitHandler 반환값=false / 데이터 로드 여부=false (행 수=" + dlt_userList.getRowCount() + ")");
                $p.hideProcessMessage();
            }
        }, "chk_handler", 500);
    }
};
